import{_ as l,l as n,o as e,c as s,v as i,p as o,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"LSM 与 SELinux","description":"","frontmatter":{"title":"LSM 与 SELinux","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-selinux.md","filePath":"cs/lsm-selinux.md","lastUpdated":1789023840000}'),u={name:"cs/lsm-selinux.md"};function S(x,a,h,E,m,L){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="lsm-与-selinux" tabindex="-1">LSM 与 SELinux <a class="header-anchor" href="#lsm-与-selinux" aria-label="Permalink to &quot;LSM 与 SELinux&quot;">​</a></h1><div class="epigraph"><p>LSM 在 inode、进程、套接字等对象上留钩子；SELinux 用类型强制把「谁能碰谁」写成策略，而不是再加一位 cap。</p><footer>—— 据 Wright et al., Linux Security Modules；NSA/SELinux 文档；[xattr](/cs/xattr-acl) 为标签存放先修</footer></div><p><a href="/cs/linux-capabilities">capabilities</a> 仍是「能做特权操作吗」。强制访问要问 <strong>这个 httpd 能不能写那个 shadow</strong>。缺口是 LSM 框架与 SELinux 作为实例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钩子：<code>inode_permission</code>、<code>file_open</code>、<code>socket_connect</code>… 多个 LSM 可叠（新内核）。SELinux：类型、域转换、<code>security.*</code> xattr。缺口：策略语言不是本课作业；Permissive vs Enforcing；与 <a href="/cs/overlayfs">overlay</a> 标签 copy-up。本课不写如何破解 SELinux。</p><p><span class="marginnote">AppArmor 下一课用路径。SELinux 用类型，与 inode 绑定更紧。audit 后课记拒绝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>打开文件：VFS 权限 → LSM 钩 → SELinux 查 AVC 缓存。对照 <a href="/cs/netfilter-conntrack">netfilter</a>：一个管包，一个管对象标签。对照 ASan：一个防内存 bug，一个防越权。对照 FUSE：用户 FS 也要过钩。</p>',8)),(e(),o(p,null,{default:t(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20VFS%5B%22DAC%22%5D%0A%20%20VFS%20--%3E%20LSM%5B%22LSM%20%E9%92%A9%22%5D%0A%20%20LSM%20--%3E%20AVC%5B%22SELinux%20AVC%22%5D%0A%20%20AVC%20--%3E%7C%22%E6%8B%92%E7%BB%9D%22%7C%20EACCES%5B%22EACCES%20%E5%B9%B6%20audit%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LSM 让强制策略成为内核可插层，SELinux 把系统做成类型图。它不替代补丁。不要写成合规广告。与 <a href="/cs/kpti-os">KPTI</a>：正交。与容器：需正确 label 与类别。</p><p>策略错误会拒绝合法服务，看起来像权限 bug。</p><p>实现上：AVC 缓存命中才快，首次决策要走策略。域转换在 exec 时发生，httpd 的子进程类型由策略决定。Permissive 只记不拦，容易误以为已经保护。 读法上只引用<a href="/cs/linux-capabilities">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>LSM 与 SELinux</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MLS 等级的全部。不保证微内核的同构。下一课路径强制：AppArmor。</p><p>版本字段会变，课序钉的是机制对象「LSM 与 SELinux」，不是某一主线内核的结构体名。 后课默认：对象可打类型，钩子强制。按路径的 MAC，下一课 AppArmor。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM 提供钩；SELinux 用类型强制。</li><li>标签常在 xattr；拒绝进 audit。</li><li>AppArmor 是下一课。</li><li>出处：Wright LSM；SELinux；Linux security。</li></ul>',11))])}const f=l(u,[["render",S]]);export{A as __pageData,f as default};
